<template>
  <main class="admin-page">
    <header class="admin-header"><router-link to="/" class="admin-brand"><Anchor :size="24" /><strong>海战棋</strong></router-link><router-link to="/" class="admin-back"><ArrowLeft :size="16" />返回指挥部</router-link></header>
    <section v-if="checking" class="admin-loading" aria-busy="true"><AppSkeleton variant="detail" :rows="4" label="正在加载管理中心" /></section>
    <section v-else-if="!authorized" class="admin-status"><ShieldAlert :size="28" /><h1>无法访问管理中心</h1><p role="alert">{{ error || '此页面仅对管理员开放' }}</p><router-link to="/login?redirect=/admin">切换账号</router-link></section>
    <template v-else>
      <div class="admin-title"><ShieldCheck :size="24" /><h1>管理中心</h1><span>{{ nickname }}</span></div>
      <div class="admin-workspace">
        <section class="recipient-section" aria-label="通知收件人">
          <h2>收件人 <span>{{ selected.length }}</span></h2>
          <form class="account-search" @submit.prevent="search"><Search :size="17" /><input v-model="query" aria-label="搜索账号" placeholder="昵称、邮箱或账号 ID" maxlength="254" /><button type="submit" title="搜索账号" aria-label="搜索账号" :disabled="searching"><ArrowRight :size="17" /></button></form>
          <div class="account-results" :aria-busy="searching">
            <AppSkeleton v-if="searching" :rows="5" label="正在搜索账号" />
            <template v-else><p v-if="!users.length" class="empty-result">没有符合条件的账号</p><label v-for="user in users" :key="user.id" class="account-result"><input type="checkbox" :checked="selected.some(item=>item.id===user.id)" :disabled="sending" @change="select(user,$event.target.checked)" /><NavalAvatar :person="{name:user.nickname,avatarUrl:user.avatarUrl,registered:true}" :size="18" /><span><strong>{{ user.nickname }}</strong><small>ID {{ user.id }}<template v-if="user.email"> · {{ user.email }}</template></small></span></label></template>
          </div>
          <div v-if="selected.length" class="selected-accounts"><h3>已选账号</h3><ul><li v-for="user in selected" :key="user.id"><span>{{ user.nickname }}</span><button type="button" :aria-label="'移除收件人 '+user.nickname" :title="'移除 '+user.nickname" :disabled="sending" @click="select(user,false)"><X :size="13" /></button></li></ul></div>
        </section>
        <section class="compose-section" aria-label="发送消息通知"><h2><Mail :size="18" />消息通知</h2><form @submit.prevent="prepareSend">
          <label>标题<input v-model="title" maxlength="100" placeholder="通知标题" required :disabled="sending" /></label>
          <label>内容<textarea v-model="content" maxlength="3000" rows="8" placeholder="通知内容" required :disabled="sending" /></label>
          <div class="gift-option"><label class="gift-toggle"><input v-model="withGift" type="checkbox" :disabled="sending" /><Gift :size="17" />附赠金币</label><label v-if="withGift" class="gift-amount"><Coins :size="16" /><input v-model.number="coins" type="number" min="1" max="1000000" step="1" aria-label="每位收件人赠送金币" required :disabled="sending" /><span>金币 / 人</span></label></div>
          <section class="item-gift-section" aria-label="附赠商城物品"><label class="gift-toggle"><input v-model="withItems" type="checkbox" :disabled="sending" /><Package :size="17" />附赠物品</label><div v-if="withItems" class="gift-item-list" :aria-busy="catalogLoading">
            <AppSkeleton v-if="catalogLoading" variant="products" :rows="3" label="正在读取赠送物品" />
            <template v-else><div v-for="item in giftRows" :key="item.id" class="gift-item-row"><label class="gift-item-choice"><input v-model="item.selected" type="checkbox" :disabled="sending" /><span class="gift-item-art" :class="{'bubble-art':isBubbleItem(item.id)}" :style="shopArtwork(item.id)" /><span>{{ item.name }}</span></label><div v-if="item.selected" class="gift-item-settings"><label>份数<input v-model.number="item.quantity" type="number" min="1" max="99" step="1" :aria-label="`${item.name}份数`" :disabled="sending" /></label><label class="gift-item-duration">领取后有效<input v-model.number="item.durationValue" type="number" min="1" :max="Math.floor(8760/item.durationUnit)" step="1" :aria-label="`${item.name}有效时长`" :disabled="sending" /><select v-model.number="item.durationUnit" :aria-label="`${item.name}时间单位`" :disabled="sending"><option :value="1">小时</option><option :value="24">天</option></select></label></div></div></template>
          </div></section>
          <div v-if="withGift || withItems" class="gift-mail-terms"><Clock3 :size="14" /><span>领取期限 24 小时</span></div>
          <footer class="compose-footer"><span>{{ selected.length }} 位收件人<template v-if="withGift"> · 共 {{ totalCoins }} 金币</template><template v-if="attachments.length"> · 每人 {{ attachmentCount }} 件物品</template></span><button class="send-notification" :disabled="sending || !selected.length || catalogLoading"><Send :size="16" />{{ sending ? '发送中...' : '发送通知' }}</button></footer>
        </form></section>
      </div>
      <AppDialog :open="confirming" title="确认发送通知" @close="confirming=false"><h2 class="confirm-heading">确认发送</h2><p class="confirm-summary">向 {{ selected.map(user=>user.nickname).join('、') }} 发送「{{ title.trim() }}」<template v-if="withGift">，每人附赠 {{ coins }} 金币</template><template v-if="attachments.length">及 {{ attachmentCount }} 件物品</template>。</p><ul v-if="attachments.length" class="confirm-items"><li v-for="item in attachments" :key="item.itemId">{{ giftRows.find(row=>row.id===item.itemId)?.name }} × {{ item.quantity }}<small>领取后 {{ item.durationHours }} 小时</small></li></ul><button class="send-notification confirm-send" :disabled="sending" @click="send"><Send :size="16" />确认发送</button></AppDialog>
    </template>
  </main>
</template>

<style scoped>.admin-loading{max-width:1120px;margin:70px auto;min-height:260px}</style>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { Anchor, ArrowLeft, ArrowRight, Clock3, Coins, Gift, Mail, Package, Search, Send, ShieldAlert, ShieldCheck, X } from 'lucide-vue-next'
import AppDialog from '../components/AppDialog.vue'
import AppSkeleton from '../components/AppSkeleton.vue'
import NavalAvatar from './game/NavalAvatar.vue'
import client from '../api/client'
import { getAdminShopItems, searchAccounts, sendNotification } from '../api/account'
import { isBubbleItem, shopArtwork } from '../games/shopArtwork'
import { notifyError, notifySuccess } from '../services/notice'

const checking=ref(true), authorized=ref(false), nickname=ref(''), error=ref(''), success=ref('')
const query=ref(''), users=ref([]), selected=ref([]), searching=ref(false), searchError=ref('')
const title=ref(''), content=ref(''), withGift=ref(false), coins=ref(100), sending=ref(false), confirming=ref(false)
const withItems=ref(false),giftRows=ref([]),catalogLoading=ref(false)
const attachments=computed(()=>withItems.value?giftRows.value.filter(item=>item.selected).map(item=>({itemId:item.id,quantity:item.quantity,durationHours:item.durationValue*item.durationUnit})):[])
const attachmentCount=computed(()=>attachments.value.reduce((sum,item)=>sum+Number(item.quantity||0),0))
const totalCoins=computed(()=>selected.value.length * (Number(coins.value)||0))
let requestId=crypto.randomUUID(), searchVersion=0
watch([title,content,withGift,coins,()=>JSON.stringify(attachments.value),()=>selected.value.map(user=>user.id).join(',')],()=>{requestId=crypto.randomUUID();success.value=''})
watch(error,value=>{if(value && authorized.value)notifyError(value)},{flush:'sync'})
watch(searchError,value=>{if(value)notifyError(value)},{flush:'sync'})
watch(success,value=>{if(value)notifySuccess(value)},{flush:'sync'})
function select(user,checked){if(checked&&!selected.value.some(item=>item.id===user.id)){if(selected.value.length>=100){searchError.value='一次最多选择 100 个账号';return}selected.value.push(user)}else if(!checked)selected.value=selected.value.filter(item=>item.id!==user.id)}
async function search(){const version=++searchVersion;searching.value=true;searchError.value='';try{const value=await searchAccounts(query.value.trim());if(version===searchVersion)users.value=Array.isArray(value)?value:value.items||[]}catch(e){if(version===searchVersion)searchError.value=e.message}finally{if(version===searchVersion)searching.value=false}}
function prepareSend(){error.value='';success.value='';if(!selected.value.length||!title.value.trim()||!content.value.trim()){error.value='请选择收件人并填写标题和内容';return}if(withGift.value&&(!Number.isSafeInteger(coins.value)||coins.value<1||coins.value>1000000)){error.value='金币数量须为 1 至 1000000 的整数';return}if(withItems.value&&(!attachments.value.length||attachmentCount.value>100||attachments.value.some(item=>!Number.isSafeInteger(item.quantity)||item.quantity<1||item.quantity>99||!Number.isSafeInteger(item.durationHours)||item.durationHours<1||item.durationHours>8760))){error.value='请选择赠送物品，最多 100 件，有效时长为 1 至 8760 小时';return}confirming.value=true}
async function send(){
  if(sending.value)return
  confirming.value=false;sending.value=true;error.value='';success.value=''
  try{await sendNotification({userIds:selected.value.map(user=>user.id),title:title.value.trim(),content:content.value.trim(),coins:withGift.value?coins.value:0,items:attachments.value,requestId});success.value=`已向 ${selected.value.length} 位玩家发送通知`;requestId=crypto.randomUUID()}
  catch(e){error.value=e.message}finally{sending.value=false}
}
async function loadCatalog(){catalogLoading.value=true;try{const items=await getAdminShopItems();giftRows.value=items.map(item=>({...item,selected:false,quantity:1,durationValue:item.durationHours>24?item.durationHours/24:item.durationHours,durationUnit:item.durationHours>24?24:1}))}catch(e){error.value=e.message}finally{catalogLoading.value=false}}
onMounted(async()=>{try{if(!localStorage.getItem('navy_token')){error.value='请使用管理员账号登录';return}const account=await client.get('/account');authorized.value=account.isAdmin===true;nickname.value=account.nickname;if(authorized.value){checking.value=false;await Promise.all([search(),loadCatalog()])}}catch(e){error.value=e.message}finally{checking.value=false}})
</script>

<style scoped>
.admin-page{min-height:100dvh;background:#f4f8f8;padding:0 24px 40px;color:#456a77}.admin-header{max-width:1120px;margin:auto;height:76px;display:flex;align-items:center;justify-content:space-between;gap:16px}.admin-brand,.admin-back{display:flex;align-items:center;gap:8px}.admin-brand strong{font-size:21px}.admin-brand>svg{color:#e8984e}.admin-back{font-size:12px;color:#79919a}.admin-title{max-width:1120px;margin:28px auto;display:flex;align-items:center;gap:10px;border-bottom:1px solid #dce6e9;padding-bottom:22px}.admin-title>svg{color:var(--color-primary)}.admin-title h1{font-size:24px}.admin-title>span{margin-left:auto;font-size:12px;color:#839ba4;overflow-wrap:anywhere}.admin-workspace{max-width:1120px;margin:auto;display:grid;grid-template-columns:minmax(240px,330px) minmax(0,1fr);gap:40px}.recipient-section{border-right:1px solid #dce6e9;padding-right:26px;min-width:0}.admin-workspace h2{display:flex;align-items:center;gap:8px;font-size:14px;margin-bottom:18px}.recipient-section h2>span{font-size:11px;font-weight:400;color:#8b9fa5;margin-left:auto}.account-search{display:flex;align-items:center;gap:8px;height:40px;padding:0 9px;border:1px solid #d1e0e5;background:#fff;border-radius:4px}.account-search>svg{color:#8b9fa5;flex-shrink:0}.account-search input{min-width:0;flex:1;width:0;border:0;outline:0;font-size:12px;background:transparent;color:inherit}.account-search button{width:26px;height:30px;display:grid;place-items:center;background:transparent;color:var(--color-primary-strong)}.account-results{max-height:430px;overflow:auto;margin-top:14px}.account-result{display:flex;align-items:center;gap:10px;padding:12px 0;border-bottom:1px solid #e3ebed;cursor:pointer}.account-result>input{accent-color:var(--color-primary);flex-shrink:0}.account-result>span{min-width:0}.account-result strong{font-size:12px;font-weight:500;display:block;overflow-wrap:anywhere}.account-result small{display:block;margin-top:4px;font-size:10px;overflow-wrap:anywhere;color:#90a3aa}.selected-accounts{padding-top:22px}.selected-accounts h3{font-size:11px;color:#8b9fa5;font-weight:400}.selected-accounts ul{list-style:none;padding:0;margin-top:8px;display:flex;gap:6px;flex-wrap:wrap}.selected-accounts li{display:flex;align-items:center;gap:5px;background:var(--color-primary-bg);padding:4px 6px;font-size:11px;border-radius:4px;max-width:100%;overflow-wrap:anywhere}.selected-accounts li>span{min-width:0}.selected-accounts button{display:grid;place-items:center;flex-shrink:0;width:21px;height:21px;background:transparent;color:#927d6a}.compose-section{min-width:0}.compose-section form{display:flex;flex-direction:column;gap:20px}.compose-section form>label{display:flex;flex-direction:column;gap:8px;font-size:12px}.compose-section input:not([type=checkbox]),.compose-section textarea{width:100%;min-width:0;border:1px solid #d1e0e5;border-radius:4px;padding:10px 12px;background:#fff;color:#456a77;font-size:13px;resize:vertical}.compose-section textarea{min-height:160px;max-height:440px;line-height:1.7}.gift-option{display:flex;align-items:center;flex-wrap:wrap;gap:14px;min-height:38px}.gift-toggle,.gift-amount{display:flex;align-items:center;gap:8px;font-size:12px}.gift-toggle>input{accent-color:var(--color-primary)}.gift-toggle svg,.gift-amount svg{color:#b3884d}.compose-section .gift-amount input{width:110px;height:36px;padding:6px 8px;font-variant-numeric:tabular-nums}.gift-amount span{font-size:11px;color:#8b9fa5}.compose-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid #dce6e9;padding-top:20px;margin-top:8px}.compose-footer>span{font-size:11px;color:#8b9fa5}.send-notification{display:flex;align-items:center;justify-content:center;gap:7px;min-height:39px;flex-shrink:0;padding:9px 15px;border-radius:4px;background:var(--color-primary);color:#fff;font-size:12px}.admin-status{max-width:1120px;margin:80px auto;text-align:center;display:flex;flex-direction:column;align-items:center;gap:16px;font-size:13px}.admin-status h1{font-size:20px}.admin-status>svg{color:#b18b56}.admin-error{font-size:12px;color:#b45f50;overflow-wrap:anywhere;line-height:1.7}.admin-success{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--color-primary)}.empty-result{font-size:12px;color:#90a3aa;text-align:center;padding:28px 0}.confirm-heading{font-size:18px;margin-bottom:15px}.confirm-summary{font-size:13px;line-height:1.8;overflow-wrap:anywhere;padding-right:8px}.confirm-send{margin-top:22px;margin-left:auto}@media(max-width:700px){.admin-page{padding:0 18px 28px}.admin-header{height:64px}.admin-title{margin-top:20px;align-items:flex-start}.admin-title h1{font-size:21px}.admin-workspace{grid-template-columns:minmax(0,1fr);gap:30px}.recipient-section{border-right:0;border-bottom:1px solid #dce6e9;padding:0 0 22px}.account-results{max-height:210px}.compose-footer{flex-wrap:wrap}.admin-title>span{max-width:40%;text-align:right}.selected-accounts{padding-top:14px}}
</style>
<style scoped>
.item-gift-section{border-top:1px solid #e1e8eb;padding-top:18px}.gift-item-list{margin-top:12px}.gift-item-row{padding:11px 0;border-bottom:1px solid #e4eaed}.gift-item-row:last-child{border-bottom:0}.gift-item-choice{display:flex;align-items:center;gap:10px;font-size:12px;cursor:pointer;min-height:38px}.gift-item-choice>input{flex-shrink:0}.gift-item-art{display:block;width:38px;height:38px;flex-shrink:0;background-size:contain;background-position:center;background-repeat:no-repeat}.gift-item-art.bubble-art{background-size:200% 100%;background-position:left center}.gift-item-settings{display:flex;align-items:center;flex-wrap:wrap;gap:10px 18px;padding:10px 0 0 26px}.gift-item-settings>label{display:flex;align-items:center;gap:7px;font-size:11px;color:#8b9ca4}.compose-section .gift-item-settings input{width:72px;height:32px;padding:4px 7px;font-size:12px}.gift-item-settings select{height:32px;padding:4px 6px;border:1px solid #d1e0e5;border-radius:4px;background:#fff;color:#67838e;font-size:11px}.gift-mail-terms{display:flex;align-items:center;gap:6px;color:#a28b75;font-size:11px}.confirm-items{list-style:none;padding:12px 0 0;margin:0}.confirm-items>li{display:flex;align-items:center;flex-wrap:wrap;gap:5px 12px;padding:7px 0;font-size:12px;border-bottom:1px solid #e1e8eb}.confirm-items small{font-size:10px;color:#93a2a8;margin-left:auto}@media(max-width:390px){.gift-item-settings{padding-left:0;gap:8px}.gift-item-settings>label{flex-wrap:wrap}.compose-section .gift-item-settings input{width:64px}}
</style>
